function openBackgroundDb(){return new Promise((ok,no)=>{const request=indexedDB.open('luskm-backgrounds',1);request.onupgradeneeded=()=>request.result.createObjectStore('images',{keyPath:'id',autoIncrement:true});request.onsuccess=()=>ok(request.result);request.onerror=()=>no(request.error)})}
async function saveBackground(file){const db=await openBackgroundDb();return new Promise((ok,no)=>{const request=db.transaction('images','readwrite').objectStore('images').add({blob:file,createdAt:Date.now()});request.onsuccess=()=>ok(request.result);request.onerror=()=>no(request.error)})}
async function getSavedBackgrounds(){const db=await openBackgroundDb();return new Promise((ok,no)=>{const request=db.transaction('images').objectStore('images').getAll();request.onsuccess=()=>ok(request.result);request.onerror=()=>no(request.error)})}
async function deleteSavedBackground(id){const db=await openBackgroundDb();return new Promise((ok,no)=>{const request=db.transaction('images','readwrite').objectStore('images').delete(id);request.onsuccess=()=>ok();request.onerror=()=>no(request.error)})}
function bindBackgroundCard(card){card.onclick=async()=>{state.bg=null;inputs.bg.value='';const selected=card.dataset.bg==='default'?(assets.styleBackgrounds[state.style]||null):assets.backgrounds[card.dataset.bg];state.libraryBg=selected;state.backgroundByStyle[state.style]=selected;document.querySelectorAll('.background-card').forEach(x=>x.classList.toggle('active',x===card));document.querySelector('#backgroundTrigger').classList.add('loaded');document.querySelector('#backgroundTrigger small').textContent='已选择背景';await recolor();draw();dlg.close()};card.ondblclick=event=>{event.preventDefault();event.stopPropagation();const selected=card.dataset.bg==='default'?(assets.styleBackgrounds[state.style]||null):assets.backgrounds[card.dataset.bg];openCrop(selected)}}
async function addSavedBackground(record){const key=`saved-${record.id}`,url=URL.createObjectURL(record.blob),image=await load(url);assets.backgrounds[key]=image;const card=document.createElement('button');card.type='button';card.className='background-card';card.dataset.bg=key;const thumb=document.createElement('img');thumb.src=url;thumb.alt='';const remove=document.createElement('span');remove.className='delete-background';remove.textContent='×';remove.title='删除背景';remove.onclick=async event=>{event.stopPropagation();await deleteSavedBackground(record.id);const wasActive=state.libraryBg===assets.backgrounds[key];if(wasActive){state.libraryBg=assets.styleBackgrounds[state.style]||null;state.backgroundByStyle[state.style]=state.libraryBg;await recolor();draw()}delete assets.backgrounds[key];URL.revokeObjectURL(url);card.remove()};card.append(thumb,remove);backgroundGrid.append(card);bindBackgroundCard(card);return card}
async function restoreSavedBackgrounds(){try{for(const record of await getSavedBackgrounds())await addSavedBackground(record)}catch(e){console.warn('背景库读取失败',e)}}
document.querySelector('#backgroundTrigger').onclick=()=>dlg.showModal();document.querySelector('#closeBackground').onclick=()=>dlg.close();document.querySelector('#uploadOwnBackground').onclick=()=>{dlg.close();inputs.bg.click()};document.querySelectorAll('.background-card').forEach(bindBackgroundCard);
inputs.bg.addEventListener('change',async()=>{const files=[...(inputs.bg.files||[])].filter(file=>file.type.startsWith('image/'));if(!files.length)return;let lastCard=null;try{for(const file of files){const id=await saveBackground(file);lastCard=await addSavedBackground({id,blob:file})}if(lastCard)await lastCard.onclick();document.querySelector('#backgroundTrigger small').textContent=`已保存 ${files.length} 张背景`}catch(e){document.querySelector('#backgroundTrigger small').textContent='背景保存失败';console.error(e)}});restoreSavedBackgrounds();
document.querySelector('#downloadBtn').onclick=()=>{const button=document.querySelector('#downloadBtn');if(state.style==='collection'&&!state.friend){alert('款式4必须上传微信好友码后才能下载。');return}try{draw();canvas.toBlob(blob=>{if(!blob){button.textContent='生成失败，请重试';return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.download=`收款码-${state.name||'成品'}.png`;a.href=url;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);button.textContent='下载成品 PNG'},'image/png')}catch(e){console.error(e);button.textContent='下载失败，请刷新重试'}};document.querySelector('#resetBtn').onclick=async()=>{const defaultBackground=Object.prototype.hasOwnProperty.call(state.backgroundByStyle,state.style)?state.backgroundByStyle[state.style]:(assets.styleBackgrounds[state.style]||null);Object.assign(state,{bg:null,libraryBg:defaultBackground,avatar:null,wechat:null,appreciate:null,alipay:null,friend:null,visitor1:null,visitor2:null,name:'昵称',english:'nickname',quote:'感谢你的支持与喜欢',quote2:'感谢阅读，祝你天天开心',appleTitle:'Blue chime',appleLine:'/ 风铃　　[我们会在春天短暂相逢]',qrColor:null});Object.values(inputs).forEach(i=>i.value='');document.querySelectorAll('.upload-card').forEach(x=>x.classList.remove('loaded'));document.querySelector('#backgroundTrigger small').textContent=state.libraryBg?'已选择背景':'上传或从背景库选择';document.querySelector('#nameInput').value='昵称';document.querySelector('#quoteInput').value=state.style==='apple'?state.appleLine:'感谢你的支持与喜欢';document.querySelector('#quote2Input').value='感谢阅读，祝你天天开心';document.querySelector('#appleTitleInput').value='Blue chime';document.querySelector('#englishInput').value='nickname';document.querySelectorAll('.background-card').forEach(b=>b.classList.toggle('active',assets.backgrounds[b.dataset.bg]===state.libraryBg));await recolor();draw()};

function renderLibraryPreviews(){const keep={style:state.style,bg:state.bg,libraryBg:state.libraryBg,wechat:state.wechat,appreciate:state.appreciate,alipay:state.alipay,friend:state.friend};state.wechat=null;state.appreciate=null;state.alipay=null;state.friend=null;document.querySelectorAll('.style-choice').forEach(button=>{state.style=button.dataset.style;state.bg=null;state.libraryBg=assets.previewBackgrounds[state.style]||assets.styleBackgrounds[state.style]||null;draw();const preview=document.createElement('canvas');preview.width=preview.height=1254;preview.getContext('2d').drawImage(canvas,0,0);const thumb=button.querySelector('.style-thumb');thumb.replaceChildren(preview);thumb.classList.add('canvas-preview');const editorThumb=document.querySelector(`.editor-style-card[data-style="${state.style}"] i`),editorPreview=document.createElement('canvas');editorPreview.width=editorPreview.height=1254;editorPreview.getContext('2d').drawImage(canvas,0,0);editorThumb.replaceChildren(editorPreview)});Object.assign(state,keep);arrangeEditorStyles();draw()}
Promise.all([load('./assets/default-landscape.png'),load('./assets/wing-pair-v2.png'),load('./assets/right-wing.png'),load('./assets/clip.png'),load('./assets/backgrounds/silver-stars.png'),load('./assets/backgrounds/ivory-ribbon.png'),load('./assets/backgrounds/sage-clover.png'),load('./assets/backgrounds/profile-default.png'),load('./assets/backgrounds/desktop-default.png'),load('./assets/backgrounds/collection-default.png'),load('./assets/backgrounds/social-palette.png'),load('./assets/backgrounds/white-azalea.png'),load('./assets/backgrounds/dark-book.png'),load('./assets/backgrounds/blue-wind-chime.png'),load('./assets/backgrounds/star-curtain.png')]).then(([landscape,wingSheet,rightWing,clip,stars,ribbon,clover,profileDefault,desktopDefault,collectionDefault,socialDefault,dewDefault,cardDefault,appleDefault,feedDefault])=>{Object.assign(assets,{landscape,wingSheet,leftWing:null,rightWing:null,clip,backgrounds:{...assets.backgrounds,stars,ribbon,clover,profileDefault,desktopDefault,collectionDefault,socialDefault,dewDefault,cardDefault,appleDefault,feedDefault},styleBackgrounds:{...assets.styleBackgrounds,ink:ribbon,profile:profileDefault,desktop:desktopDefault,collection:collectionDefault,social:socialDefault,dew:dewDefault,card:cardDefault,apple:appleDefault,feed:feedDefault},previewBackgrounds:{...assets.previewBackgrounds,ink:ribbon,profile:profileDefault,desktop:desktopDefault,collection:collectionDefault,social:socialDefault,dew:dewDefault,card:cardDefault,apple:appleDefault,feed:feedDefault}});renderLibraryPreviews()}).catch(()=>draw());
